/**
 * Đọc Excel Trung cấp → sinh sql-table/patches/20261003_import_VIEC_LAM_trung_cap_RUN.sql
 * Chạy: node generate_import_vieclam_trungcap.js
 */
const XLSX = require('xlsx');
const fs = require('fs');
const path = require('path');

const xlsxPath = path.join(__dirname, 'Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx');
const outSql = path.join(__dirname, '..', '..', 'sql-table', 'patches', '20261003_import_VIEC_LAM_trung_cap_RUN.sql');
const logPath = path.join(__dirname, 'import_loi.log.txt');

const ANSWERS = {
  '20201': {
    'đã có việc làm': { id: 2020101, idx: 1, name: 'Đã có việc làm (Vui lòng trả lời tiếp Mục A)' },
    'chưa có việc làm': { id: 2020102, idx: 2, name: 'Chưa có việc làm (Vui lòng trả lời tiếp Mục B)' },
    'tiếp tục học nâng cao': { id: 2020103, idx: 3, name: 'Tiếp tục học nâng cao' },
    'khác': { id: 2020104, idx: 4, name: 'Khác (Nghĩa vụ quân sự, chưa có nhu cầu tìm việc...):' },
  },
  '20202': {
    'trước khi tốt nghiệp': { id: 2020201, idx: 1, name: 'Trước khi tốt nghiệp' },
    'sau khi tốt nghiệp (trong vòng 3 tháng)': { id: 2020202, idx: 2, name: 'Sau khi tốt nghiệp (Trong vòng 3 tháng)' },
    'sau khi tốt nghiệp (từ 3 - 6 tháng)': { id: 2020203, idx: 3, name: 'Sau khi tốt nghiệp (Từ 3 - 6 tháng)' },
    'sau khi tốt nghiệp (trên 6 tháng)': { id: 2020204, idx: 4, name: 'Sau khi tốt nghiệp (Trên 6 tháng)' },
  },
  '20203': {
    'toàn thời gian (full-time)': { id: 2020301, idx: 1, name: 'Toàn thời gian (Full-time)' },
    'bán thời gian (part-time)': { id: 2020302, idx: 2, name: 'Bán thời gian (Part-time)' },
    'tự do / tự kinh doanh (freelance)': { id: 2020303, idx: 3, name: 'Tự do / Tự kinh doanh (Freelance)' },
  },
  '20204': {
    'đúng chuyên ngành đào tạo': { id: 2020401, idx: 1, name: 'Đúng chuyên ngành đào tạo' },
    'thích hợp / có liên quan đến chuyên ngành đào tạo': { id: 2020402, idx: 2, name: 'Thích hợp / Có liên quan đến chuyên ngành đào tạo' },
    'không liên quan đến chuyên ngành đào tạo': { id: 2020403, idx: 3, name: 'Không liên quan đến chuyên ngành đào tạo' },
  },
  '20206': {
    'dưới 5 triệu đồng': { id: 2020601, idx: 1, name: 'Dưới 5 triệu đồng' },
    'từ 5 triệu đến dưới 8 triệu đồng': { id: 2020602, idx: 2, name: 'Từ 5 triệu đến dưới 8 triệu đồng' },
    'từ 8 triệu đến dưới 12 triệu đồng': { id: 2020603, idx: 3, name: 'Từ 8 triệu đến dưới 12 triệu đồng' },
    'từ 12 triệu đồng trở lên': { id: 2020604, idx: 4, name: 'Từ 12 triệu đồng trở lên' },
  },
  '20207': {
    'có': { id: 2020701, idx: 1, name: 'Có' },
    'không': { id: 2020702, idx: 2, name: 'Không' },
  },
  '20208': {
    'đang trong thời gian tìm kiếm / chờ kết quả ứng tuyển': { id: 2020801, idx: 1, name: 'Đang trong thời gian tìm kiếm / Chờ kết quả ứng tuyển' },
    'cần bổ sung thêm kỹ năng chuyên môn / ngoại ngữ / tin học': { id: 2020802, idx: 2, name: 'Cần bổ sung thêm kỹ năng chuyên môn / Ngoại ngữ / Tin học' },
    'lý do cá nhân / gia đình': { id: 2020803, idx: 3, name: 'Lý do cá nhân / Gia đình' },
    'khác': { id: 2020804, idx: 4, name: 'Khác:' },
  },
};

function norm(s) {
  if (s == null) return '';
  return String(s).trim().toLowerCase().replace(/\s+/g, ' ');
}

function normCode(v) {
  if (v == null) return '';
  let s = String(v).trim();
  const m = s.match(/"?(\d+)"?/);
  if (m) return m[1];
  return s.replace(/^=/, '').replace(/"/g, '').trim();
}

function escSql(s) {
  if (s == null || s === '') return null;
  return String(s).replace(/'/g, "''");
}

function pickAnswer(mapKey, raw) {
  const k = norm(raw);
  if (!k) return null;
  const m = ANSWERS[mapKey];
  if (m[k]) return m[k];
  return null;
}

function fmtRadio(a) {
  if (!a) return null;
  return {
    doAnswerId: ';' + a.id + ';',
    doAnswerIndex: ';' + a.idx + ';',
    doAnswerContent: a.name,
  };
}

function fmtComposite(parts) {
  const valid = parts.filter(p => p && (p.content || p.id));
  if (!valid.length) return null;
  let doAnswerId = '';
  let doAnswerIndex = '';
  let doAnswerContent = '';
  for (const p of valid) {
    doAnswerId += ';' + p.id;
    doAnswerIndex += ';' + p.idx;
    doAnswerContent += '; ' + (p.content != null ? p.content : p.name || '');
  }
  return {
    doAnswerId: doAnswerId.substring(1) + ';',
    doAnswerIndex: doAnswerIndex.substring(1) + ';',
    doAnswerContent: doAnswerContent.substring(2),
  };
}

function excelDateToSql(excelNum) {
  if (excelNum == null || excelNum === '') return null;
  if (typeof excelNum === 'number') {
    const ms = (excelNum - 25569) * 86400 * 1000;
    const d = new Date(ms);
    if (!isNaN(d.getTime())) {
      const pad = n => (n < 10 ? '0' + n : '' + n);
      return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
        ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    }
  }
  return null;
}

function buildDetails(row) {
  const details = [];
  const q1raw = row[5];
  const q1other = row[6];
  const a1 = pickAnswer('20201', q1raw);
  if (a1) {
    if (norm(q1raw) === 'khác' && q1other) {
      const c = fmtComposite([
        { id: 2020104, idx: 4, content: String(q1other).trim() },
        { id: 2020105, idx: 5, content: String(q1other).trim() },
      ]);
      details.push({ questionId: 20201, sectionId: 202, orderIndex: 1, ...c });
    } else {
      details.push({ questionId: 20201, sectionId: 202, orderIndex: 1, ...fmtRadio(a1) });
    }
  }
  const branch = norm(q1raw);
  const hasJob = branch === 'đã có việc làm';
  const noJob = branch === 'chưa có việc làm';
  if (hasJob) {
    const r2 = fmtRadio(pickAnswer('20202', row[7]));
    if (r2) details.push({ questionId: 20202, sectionId: 202, orderIndex: 2, ...r2 });
    const r3 = fmtRadio(pickAnswer('20203', row[8]));
    if (r3) details.push({ questionId: 20203, sectionId: 202, orderIndex: 3, ...r3 });
    const r4 = fmtRadio(pickAnswer('20204', row[9]));
    if (r4) details.push({ questionId: 20204, sectionId: 202, orderIndex: 4, ...r4 });
    const c5 = fmtComposite([
      row[10] ? { id: 2020501, idx: 1, content: String(row[10]).trim() } : null,
      row[11] ? { id: 2020502, idx: 2, content: String(row[11]).trim() } : null,
      row[12] ? { id: 2020503, idx: 3, content: String(row[12]).trim() } : null,
      row[13] ? { id: 2020504, idx: 4, content: String(row[13]).trim() } : null,
    ]);
    if (c5) details.push({ questionId: 20205, sectionId: 202, orderIndex: 5, ...c5 });
    const r6 = fmtRadio(pickAnswer('20206', row[14]));
    if (r6) details.push({ questionId: 20206, sectionId: 202, orderIndex: 6, ...r6 });
  }
  if (noJob) {
    const r7base = pickAnswer('20207', row[15]);
    if (r7base) {
      if (norm(row[15]) === 'có' && row[16]) {
        const c7 = fmtComposite([
          { id: 2020701, idx: 1, name: 'Có' },
          { id: 2020703, idx: 3, content: String(row[16]).trim() },
        ]);
        details.push({ questionId: 20207, sectionId: 202, orderIndex: 7, ...c7 });
      } else {
        details.push({ questionId: 20207, sectionId: 202, orderIndex: 7, ...fmtRadio(r7base) });
      }
    }
    const r8raw = row[17];
    const a8 = pickAnswer('20208', r8raw);
    if (a8) {
      if (norm(r8raw) === 'khác' && row[18]) {
        const c8 = fmtComposite([
          { id: 2020804, idx: 4, content: String(row[18]).trim() },
          { id: 2020805, idx: 5, content: String(row[18]).trim() },
        ]);
        details.push({ questionId: 20208, sectionId: 202, orderIndex: 8, ...c8 });
      } else {
        details.push({ questionId: 20208, sectionId: 202, orderIndex: 8, ...fmtRadio(a8) });
      }
    }
  }
  return details;
}

const wb = XLSX.readFile(xlsxPath);
const data = XLSX.utils.sheet_to_json(wb.Sheets['PhanHoi'], { header: 1, defval: null });
const byCode = new Map();
const errors = [];

for (let i = 1; i < data.length; i++) {
  const row = data[i];
  const code = normCode(row[2]);
  if (!code) continue;
  const ts = row[0];
  const prev = byCode.get(code);
  if (!prev || (typeof ts === 'number' && typeof prev.ts === 'number' && ts >= prev.ts)) {
    byCode.set(code, { row, ts, excelRow: i + 1 });
  }
}

const students = [];
for (const [code, meta] of byCode.entries()) {
  const details = buildDetails(meta.row);
  if (!details.length) {
    errors.push('Row ' + meta.excelRow + ' SV ' + code + ': không map được câu trả lời (cột 5 trống?)');
    continue;
  }
  if (!pickAnswer('20201', meta.row[5])) {
    errors.push('Row ' + meta.excelRow + ' SV ' + code + ': tình trạng VL không khớp: ' + meta.row[5]);
    continue;
  }
  students.push({
    code,
    name: meta.row[4] ? String(meta.row[4]).trim() : '',
    created: excelDateToSql(meta.ts),
    details,
  });
}

students.sort((a, b) => a.code.localeCompare(b.code));

let sql = [];
sql.push('/*');
sql.push('	Import PollNew VIEC_LAM.2026 — Trung cấp (sinh tự động từ Excel)');
sql.push('	Nguồn: mẫu khảo sát/kết quả khảo sát cần impoert/Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx');
sql.push('	Số SV (unique Mã SV): ' + students.length);
sql.push('	Chạy SSMS → USE thienhaso_SIMS_TC_NamSaiGon → F5');
sql.push('	Bỏ qua SV đã có phiếu Plan VIEC_LAM.2026 (StudentID > 0)');
sql.push('*/');
sql.push('Use [thienhaso_SIMS_TC_NamSaiGon]');
sql.push('Go');
sql.push('Set Nocount On');
sql.push('Declare @PlanID int, @SurveyID int = 2');
sql.push('Select @PlanID = POL_NEW_Plan.PlanID From POL_NEW_Plan Where POL_NEW_Plan.PlanCode = N\'VIEC_LAM.2026\'');
sql.push('If @PlanID Is Null');
sql.push('Begin');
sql.push('	Raiserror(N\'Chưa có Plan VIEC_LAM.2026 — chạy patch seed mẫu 2.\', 16, 1)');
sql.push('	Return');
sql.push('End');
sql.push('Declare @Ok int = 0, @Skip int = 0, @Err int = 0');
sql.push('');

for (const st of students) {
  const createdClause = st.created
    ? "Cast(N'" + st.created + "' As DateTime)"
    : 'GetDate()';
  sql.push('Begin Try');
  sql.push('	Declare @StudentCode nvarchar(50) = N\'' + escSql(st.code) + '\'');
  sql.push('	Declare @StudentID bigint, @Username nvarchar(50), @ResponseID bigint');
  sql.push('	Select Top 1 @StudentID = SIM_Student.StudentID From SIM_Student Where SIM_Student.StudentCode = @StudentCode And SIM_Student.IsDeleted = 0');
  sql.push('	If @StudentID Is Null');
  sql.push('	Begin');
  sql.push('		Set @Err = @Err + 1');
  sql.push('		Print N\'Lỗi: không tìm thấy SV \' + @StudentCode');
  sql.push('	End');
  sql.push('	Else If Exists (');
  sql.push('		Select 1 From POL_NEW_Response');
  sql.push('		Inner Join POL_NEW_Plan On POL_NEW_Plan.PlanID = POL_NEW_Response.PlanID');
  sql.push('		Where POL_NEW_Plan.PlanCode = N\'VIEC_LAM.2026\'');
  sql.push('			And POL_NEW_Response.StudentID = @StudentID');
  sql.push('			And POL_NEW_Response.IsDeleted = 0');
  sql.push('	)');
  sql.push('	Begin');
  sql.push('		Set @Skip = @Skip + 1');
  sql.push('	End');
  sql.push('	Else');
  sql.push('	Begin');
  sql.push('		Select Top 1 @Username = SYS_User.Username From SYS_User Where SYS_User.StudentID = @StudentID And SYS_User.IsActived = 1');
  sql.push('		Insert Into POL_NEW_Response (');
  sql.push('			PlanID, SurveyID, Username, StudentID, PersonCode, PersonName, FullName,');
  sql.push('			Status, Description, CreatedUser, CreatedDate');
  sql.push('		)');
  sql.push('		Select');
  sql.push('			@PlanID,');
  sql.push('			@SurveyID,');
  sql.push('			@Username,');
  sql.push('			@StudentID,');
  sql.push('			@StudentCode,');
  sql.push('			Left(SIM_Student.StudentFirstName + N\' \' + SIM_Student.StudentLastName, 50),');
  sql.push('			Left(SIM_Student.StudentFirstName + N\' \' + SIM_Student.StudentLastName, 100),');
  sql.push('			1,');
  sql.push('			N\'Import Excel Trung cấp 2026\',');
  sql.push('			N\'import_excel\',');
  sql.push('			' + createdClause);
  sql.push('		From SIM_Student');
  sql.push('		Where SIM_Student.StudentID = @StudentID');
  sql.push('		Set @ResponseID = Cast(Scope_Identity() As bigint)');
  for (const d of st.details) {
    sql.push('		Insert Into POL_NEW_ResponseDetail (ResponseID, QuestionID, SectionID, OrderIndex, DoAnswerID, DoAnswerIndex, DoAnswerContent)');
    sql.push('		Values (@ResponseID, ' + d.questionId + ', ' + d.sectionId + ', ' + d.orderIndex +
      ', N\'' + escSql(d.doAnswerId) + '\', N\'' + escSql(d.doAnswerIndex) + '\', N\'' + escSql(d.doAnswerContent) + '\')');
  }
  sql.push('		Set @Ok = @Ok + 1');
  sql.push('	End');
  sql.push('End Try');
  sql.push('Begin Catch');
  sql.push('	Set @Err = @Err + 1');
  sql.push('	Print N\'Lỗi SV \' + IsNull(@StudentCode, N\'?\') + N\': \' + Error_Message()');
  sql.push('End Catch');
  sql.push('');
}

sql.push('Select @Ok As DaImport, @Skip As BoQuaDaCoPhieu, @Err As Loi');
sql.push('Go');

fs.writeFileSync(outSql, sql.join('\r\n'), 'utf8');
fs.writeFileSync(logPath, errors.join('\r\n') + (errors.length ? '\r\n' : '') + 'Imported rows prepared: ' + students.length + '\r\n', 'utf8');
console.log('Wrote', outSql);
console.log('Students', students.length, 'errors', errors.length);
if (errors.length) console.log('See', logPath);

