const XLSX = require('xlsx');
const path = require('path');
const data = XLSX.utils.sheet_to_json(
  XLSX.readFile(path.join(__dirname, 'Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx')).Sheets['PhanHoi'],
  { header: 1, defval: null }
);
function normCode(v) {
  if (v == null) return '';
  let s = String(v).trim();
  const m = s.match(/"?(\d+)"?/);
  if (m) return m[1];
  return s.replace(/^=/, '').replace(/"/g, '').trim();
}
const COL_STT = 2;
const COL_MSSV = 3;
let sttN = 0, mssvN = 0;
const uniqStt = new Set();
const uniqMssv = new Set();
for (let i = 1; i < data.length; i++) {
  const c2 = normCode(data[i][COL_STT]);
  const c3 = normCode(data[i][COL_MSSV]);
  if (c2) { sttN++; uniqStt.add(c2); }
  if (c3) { mssvN++; uniqMssv.add(c3); }
}
console.log('Rows with col2 STT lookup:', sttN, 'unique', uniqStt.size);
console.log('Rows with col3 MSSV:', mssvN, 'unique', uniqMssv.size);
let diff = 0;
for (let i = 1; i < data.length; i++) {
  const c2 = normCode(data[i][COL_STT]);
  const c3 = normCode(data[i][COL_MSSV]);
  if (c2 && c3 && c2 !== c3) diff++;
}
console.log('Rows where col2 != col3 (both filled):', diff);

