/**
 * Sinh SQL đối chiếu MSSV Excel vs SIM_Student vs POL_NEW_Response (VIEC_LAM.2026)
 * Chạy: node generate_check_import_thieu.js
 * SSMS F5: sql-table/patches/20261003_check_VIEC_LAM_trung_cap_con_thieu.sql
 */
const XLSX = require('xlsx');
const fs = require('fs');
const path = require('path');

const xlsxPath = path.join(__dirname, 'Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx');
const outSql = path.join(__dirname, '..', '..', 'sql-table', 'patches', '20261003_check_VIEC_LAM_trung_cap_con_thieu.sql');
const outTxt = path.join(__dirname, 'ma_sv_chua_duoc_import.txt');
const COL_MSSV = 3;

function normCode(v) {
  if (v == null) return '';
  let s = String(v).trim();
  const m = s.match(/"?(\d+)"?/);
  if (m) return m[1];
  return s.replace(/^=/, '').replace(/"/g, '').trim();
}

const wb = XLSX.readFile(xlsxPath);
const data = XLSX.utils.sheet_to_json(wb.Sheets['PhanHoi'], { header: 1, defval: null });
const byCode = new Map();
let rowCountMssv = 0;
const dupCount = {};

for (let i = 1; i < data.length; i++) {
  const row = data[i];
  const code = normCode(row[COL_MSSV]);
  if (!code) continue;
  rowCountMssv++;
  dupCount[code] = (dupCount[code] || 0) + 1;
  const ts = row[0];
  const prev = byCode.get(code);
  if (!prev || (typeof ts === 'number' && typeof prev.ts === 'number' && ts >= prev.ts)) {
    byCode.set(code, { ts, name: row[4] ? String(row[4]).trim() : '' });
  }
}

const codes = Array.from(byCode.keys()).sort();

let sql = [];
sql.push('/*');
sql.push('	Đối chiếu import VIEC_LAM.2026 Trung cấp — mã SV Excel (MSSV) vs DB');
sql.push('	Dòng Excel có MSSV: ' + rowCountMssv + ' | Mã unique (sau gộp trùng): ' + codes.length);
sql.push('	Chạy SSMS sau khi import — xem result set 2 và 3 (chưa có phiếu / không có SV)');
sql.push('*/');
sql.push('Use [thienhaso_SIMS_TC_NamSaiGon]');
sql.push('Go');
sql.push('If Object_Id(N\'tempdb..#MssvExcel\') Is Not Null Drop Table #MssvExcel');
sql.push('Create Table #MssvExcel (');
sql.push('	StudentCode nvarchar(50) Not Null Primary Key,');
sql.push('	HoTenExcel nvarchar(200) Null');
sql.push(')');
sql.push('');

const batchSize = 200;
for (let i = 0; i < codes.length; i += batchSize) {
  const chunk = codes.slice(i, i + batchSize);
  sql.push('Insert Into #MssvExcel (StudentCode, HoTenExcel)');
  sql.push('Values');
  const vals = chunk.map(c => {
    const meta = byCode.get(c);
    const name = (meta.name || '').replace(/'/g, "''");
    return '\t(N\'' + c + '\', N\'' + name + '\')';
  });
  sql.push(vals.join(',\r\n'));
  sql.push('Go');
}

sql.push('Set Nocount On');
sql.push('Declare @PlanID int');
sql.push('Select @PlanID = POL_NEW_Plan.PlanID From POL_NEW_Plan Where POL_NEW_Plan.PlanCode = N\'VIEC_LAM.2026\'');
sql.push('');
sql.push('/* 1. Tóm tắt */');
sql.push('Select');
sql.push('\t(Select Count(*) From #MssvExcel) As MaUniqueTuExcel,');
sql.push('\t(Select Count(*) From #MssvExcel e Inner Join SIM_Student s On s.StudentCode = e.StudentCode And s.IsDeleted = 0) As CoTrongSIM_Student,');
sql.push('\t(Select Count(*) From #MssvExcel e');
sql.push('\t\tInner Join SIM_Student s On s.StudentCode = e.StudentCode And s.IsDeleted = 0');
sql.push('\t\tInner Join POL_NEW_Response r On r.StudentID = s.StudentID And r.PlanID = @PlanID And r.IsDeleted = 0) As DaCoPhieuVIEC_LAM,');
sql.push('\t(Select Count(*) From #MssvExcel e');
sql.push('\t\tWhere Not Exists (Select 1 From SIM_Student s Where s.StudentCode = e.StudentCode And s.IsDeleted = 0)) As KhongCoSIM_Student,');
sql.push('\t(Select Count(*) From #MssvExcel e');
sql.push('\t\tInner Join SIM_Student s On s.StudentCode = e.StudentCode And s.IsDeleted = 0');
sql.push('\t\tWhere Not Exists (Select 1 From POL_NEW_Response r Where r.StudentID = s.StudentID And r.PlanID = @PlanID And r.IsDeleted = 0)) As CoSV_NhungChuaCoPhieu');
sql.push('Go');
sql.push('');
sql.push('/* 2. Không có trong SIM_Student → import báo Loi (thường ~3 mã) */');
sql.push('Select');
sql.push('\t#MssvExcel.StudentCode,');
sql.push('\t#MssvExcel.HoTenExcel,');
sql.push('\tN\'Không tìm thấy SIM_Student.StudentCode\' As LyDo');
sql.push('From #MssvExcel');
sql.push('Where');
sql.push('\tNot Exists (');
sql.push('\t\tSelect 1');
sql.push('\t\tFrom SIM_Student');
sql.push('\t\tWhere');
sql.push('\t\t\tSIM_Student.StudentCode = #MssvExcel.StudentCode');
sql.push('\t\t\tAnd SIM_Student.IsDeleted = 0');
sql.push('\t)');
sql.push('Order By');
sql.push('\t#MssvExcel.StudentCode');
sql.push('Go');
sql.push('');
sql.push('/* 3. Có SV nhưng chưa có phiếu VIEC_LAM.2026 → cần import lại / xử lý tay */');
sql.push('Select');
sql.push('\t#MssvExcel.StudentCode,');
sql.push('\tSIM_Student.StudentID,');
sql.push('\tSIM_Student.StudentFirstName + N\' \' + SIM_Student.StudentLastName As HoTenDB,');
sql.push('\t#MssvExcel.HoTenExcel,');
sql.push('\tN\'Chưa có POL_NEW_Response plan VIEC_LAM.2026\' As LyDo');
sql.push('From #MssvExcel');
sql.push('Inner Join SIM_Student On SIM_Student.StudentCode = #MssvExcel.StudentCode And SIM_Student.IsDeleted = 0');
sql.push('Where');
sql.push('\tNot Exists (');
sql.push('\t\tSelect 1');
sql.push('\t\tFrom POL_NEW_Response');
sql.push('\t\tWhere');
sql.push('\t\t\tPOL_NEW_Response.PlanID = @PlanID');
sql.push('\t\t\tAnd POL_NEW_Response.StudentID = SIM_Student.StudentID');
sql.push('\t\t\tAnd POL_NEW_Response.IsDeleted = 0');
sql.push('\t)');
sql.push('Order By');
sql.push('\t#MssvExcel.StudentCode');
sql.push('Go');
sql.push('');
sql.push('/* 4. Đã import OK (tham khảo) */');
sql.push('Select Top 50');
sql.push('\t#MssvExcel.StudentCode,');
sql.push('\tPOL_NEW_Response.ResponseID,');
sql.push('\tPOL_NEW_Response.CreatedDate,');
sql.push('\tPOL_NEW_Response.CreatedUser');
sql.push('From #MssvExcel');
sql.push('Inner Join SIM_Student On SIM_Student.StudentCode = #MssvExcel.StudentCode And SIM_Student.IsDeleted = 0');
sql.push('Inner Join POL_NEW_Response On POL_NEW_Response.StudentID = SIM_Student.StudentID');
sql.push('\tAnd POL_NEW_Response.PlanID = @PlanID And POL_NEW_Response.IsDeleted = 0');
sql.push('Order By');
sql.push('\tPOL_NEW_Response.ResponseID Desc');
sql.push('Go');

fs.writeFileSync(outSql, sql.join('\r\n'), 'utf8');

const dupList = Object.entries(dupCount).filter(([, n]) => n > 1).sort((a, b) => b[1] - a[1]);
const txt = [];
txt.push('Excel: ' + rowCountMssv + ' dong co MSSV, ' + codes.length + ' ma unique');
txt.push('Import mong doi: DaImport + Loi = ' + codes.length + ' (BoQua neu da co phieu)');
txt.push('Trung MSSV trong Excel (chi giu 1 ban moi nhat): ' + dupList.length + ' ma, ' + (rowCountMssv - codes.length) + ' dong bi gop');
txt.push('');
txt.push('Chay SSMS: 20261003_check_VIEC_LAM_trung_cap_con_thieu.sql');
txt.push('  - Result 2: ma khong co SIM_Student');
txt.push('  - Result 3: co SV nhung chua co phieu');
fs.writeFileSync(outTxt, txt.join('\r\n'), 'utf8');

console.log('Wrote', outSql);
console.log('Codes unique', codes.length, 'rows MSSV', rowCountMssv);

/**
 * Xuất txt: dòng MSSV trùng trong Excel + mã không có trong SIM_Student (dump)
 * Chạy: node export_trung_va_loi.js
 */
const XLSX = require('xlsx');
const fs = require('fs');
const path = require('path');

const xlsxPath = path.join(__dirname, 'Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx');
const studentSql = path.join(__dirname, '..', '..', 'sql-table', 'new-table 01.10.2026', 'data -studenbt.sql');
const outDup = path.join(__dirname, 'danh_sach_MSSV_trung.txt');
const outLoi = path.join(__dirname, 'ma_SV_loi_khong_co_SIM_Student.txt');
const outAll = path.join(__dirname, 'tong_hop_trung_va_loi.txt');
const COL_MSSV = 3;
const COL_STT = 1;
const COL_NAME = 4;
const COL_TIME = 0;

function normCode(v) {
  if (v == null) return '';
  let s = String(v).trim();
  const m = s.match(/"?(\d+)"?/);
  if (m) return m[1];
  return s.replace(/^=/, '').replace(/"/g, '').trim();
}

function loadStudentCodesFromDump() {
  const set = new Set();
  if (!fs.existsSync(studentSql)) {
    return { set, note: 'Khong tim thay file dump: ' + studentSql };
  }
  const chunk = 4 * 1024 * 1024;
  const fd = fs.openSync(studentSql, 'r');
  const stat = fs.fstatSync(fd);
  let buf = '';
  let pos = 0;
  const re = /N'(\d{8,12})'/g;
  while (pos < stat.size) {
    const n = fs.readSync(fd, Buffer.alloc(Math.min(chunk, stat.size - pos)), 0, Math.min(chunk, stat.size - pos), pos);
    buf += n.toString('utf8', 0, n.length);
    pos += n.length;
    let m;
    while ((m = re.exec(buf)) !== null) {
      set.add(m[1]);
    }
    if (buf.length > 500000) buf = buf.slice(-200000);
  }
  fs.closeSync(fd);
  return { set, note: 'Doc dump SIM_Student, uoc tinh ma: ' + set.size };
}

const wb = XLSX.readFile(xlsxPath);
const data = XLSX.utils.sheet_to_json(wb.Sheets['PhanHoi'], { header: 1, defval: null });
const rows = [];
const countByCode = {};

for (let i = 1; i < data.length; i++) {
  const row = data[i];
  const code = normCode(row[COL_MSSV]);
  if (!code) continue;
  countByCode[code] = (countByCode[code] || 0) + 1;
  rows.push({
    excelRow: i + 1,
    code,
    stt: row[COL_STT],
    name: row[COL_NAME] != null ? String(row[COL_NAME]).trim() : '',
    time: row[COL_TIME],
  });
}

const dupRows = rows.filter(r => countByCode[r.code] > 1);
dupRows.sort((a, b) => a.code.localeCompare(b.code) || a.excelRow - b.excelRow);

const dupLines = [];
dupLines.push('DANH SACH DONG EXCEL — MSSV TRUNG (cot MSSV HSSV tu nhap)');
dupLines.push('File: Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx');
dupLines.push('Tong dong co MSSV: ' + rows.length);
dupLines.push('So ma MSSV trung (>=2 lan): ' + Object.keys(countByCode).filter(c => countByCode[c] > 1).length);
dupLines.push('Tong dong thuoc ma trung: ' + dupRows.length);
dupLines.push('(Import chi giu 1 dong / ma — Thoi gian gui moi nhat)');
dupLines.push('');
dupLines.push('ExcelRow\tMSSV\tSoLanTrongFile\tSTT\tHoTen\tThoiGianGui');
for (const r of dupRows) {
  dupLines.push(
    r.excelRow + '\t' + r.code + '\t' + countByCode[r.code] + '\t' +
    (r.stt != null ? r.stt : '') + '\t' + r.name + '\t' + (r.time != null ? r.time : '')
  );
}

const { set: dbCodes, note: dumpNote } = loadStudentCodesFromDump();
const uniqueCodes = [...new Set(rows.map(r => r.code))].sort();
const missingInDb = uniqueCodes.filter(c => !dbCodes.has(c));

const loiLines = [];
loiLines.push('MA MSSV LOI IMPORT — KHONG CO TRONG SIM_Student (StudentCode, IsDeleted=0)');
loiLines.push('Nguon doi chieu: ' + dumpNote);
loiLines.push('Luu y: Neu DB production khac dump, chay SSMS check result 2 trong 20261003_check_VIEC_LAM_trung_cap_con_thieu.sql');
loiLines.push('So ma unique Excel: ' + uniqueCodes.length);
loiLines.push('So ma khong co trong dump (uoc tinh Loi ~3): ' + missingInDb.length);
loiLines.push('');
if (missingInDb.length === 0) {
  loiLines.push('(Trong dump local: khong thieu ma — xem Messages tab luc chay import hoac chay check SQL tren DB that)');
} else {
  loiLines.push('MSSV\tHoTenExcel (dong dau tim thay)');
  for (const code of missingInDb) {
    const r = rows.find(x => x.code === code);
    loiLines.push(code + '\t' + (r ? r.name : ''));
  }
}

const all = [];
all.push('=== TONG HOP ===');
all.push('');
all.push(...dupLines);
all.push('');
all.push('========================================');
all.push('');
all.push(...loiLines);

fs.writeFileSync(outDup, dupLines.join('\r\n') + '\r\n', 'utf8');
fs.writeFileSync(outLoi, loiLines.join('\r\n') + '\r\n', 'utf8');
fs.writeFileSync(outAll, all.join('\r\n') + '\r\n', 'utf8');

console.log('Wrote', outDup);
console.log('Wrote', outLoi);
console.log('Wrote', outAll);
console.log('Dup rows', dupRows.length, 'Missing in dump', missingInDb.length, missingInDb);

