function loadStudentCodesFromDump() {
  const set = new Set();
  if (!fs.existsSync(studentSql)) {
    return { set, note: 'Khong tim thay file dump: ' + studentSql };
  }
  const readline = require('readline');
  const rl = readline.createInterface({
    input: fs.createReadStream(studentSql, { encoding: 'utf8' }),
    crlfDelay: Infinity,
  });
  const re = /VALUES \(\d+, N'([^']*)',/;
  return new Promise((resolve) => {
    rl.on('line', (line) => {
      if (line.indexOf('INSERT [dbo].[SIM_Student]') === -1) return;
      const m = line.match(re);
      if (m && m[1]) set.add(m[1]);
    });
    rl.on('close', () => {
      resolve({ set, note: 'Doc SIM_Student.StudentCode tu dump, so ma: ' + set.size });
    });
  });
}

