/**
 * Cập nhật manifest MSSV đã import VIEC_LAM.2026
 * node sync_manifest_da_import.js --record-batch "Trung cap dot 1 20261003"
 * node sync_manifest_da_import.js --from-db-export db_export.txt
 */
const fs = require('fs');
const path = require('path');
const XLSX = require('xlsx');

const dir = __dirname;
const manifestPath = path.join(dir, 'manifest_VIEC_LAM_2026_da_import.txt');
const xlsxDefault = path.join(dir, 'Khảo sát việc làm HSSV 2026 - Trung cấp.xlsx');
const studentSql = path.join(dir, '..', '..', 'sql-table', 'new-table 01.10.2026', 'data -studenbt.sql');
const COL_MSSV = 3;

function normCode(v) {
  if (v == null) return '';
  let s = String(v).trim();
  const m = s.match(/"?(\d+)"?/);
  if (m) return m[1];
  return s.replace(/^=/, '').replace(/"/g, '').trim();
}

function loadManifest() {
  const set = new Set();
  const lines = [];
  if (!fs.existsSync(manifestPath)) return { set, lines: [] };
  const raw = fs.readFileSync(manifestPath, 'utf8').split(/\r?\n/);
  for (const line of raw) {
    const t = line.trim();
    if (!t || t.indexOf('#') === 0) {
      lines.push(line);
      continue;
    }
    const code = t.split('|')[0].trim();
    if (code) {
      set.add(code);
      lines.push(line);
    }
  }
  return { set, lines: raw };
}

function loadSimStudentCodes() {
  const set = new Set();
  if (!fs.existsSync(studentSql)) return set;
  const readline = require('readline');
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: fs.createReadStream(studentSql, { encoding: 'utf16le' }),
      crlfDelay: Infinity,
    });
    const re = /VALUES \((\d+), N'([^']*)',/;
    rl.on('line', (line) => {
      if (line.indexOf('INSERT [dbo].[SIM_Student]') === -1) return;
      const m = line.match(re);
      if (m && m[2]) set.add(m[2]);
    });
    rl.on('close', () => resolve(set));
  });
}

function codesFromExcel(xlsxPath) {
  const wb = XLSX.readFile(xlsxPath);
  const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, defval: null });
  const byCode = new Map();
  for (let i = 1; i < data.length; i++) {
    const code = normCode(data[i][COL_MSSV]);
    if (!code) continue;
    const ts = data[i][0];
    const prev = byCode.get(code);
    if (!prev || (typeof ts === 'number' && typeof prev === 'number' && ts >= prev)) {
      byCode.set(code, ts);
    }
  }
  return Array.from(byCode.keys()).sort();
}

function codesFromExportFile(fp) {
  const set = new Set();
  const raw = fs.readFileSync(fp, 'utf8').split(/\r?\n/);
  for (const line of raw) {
    const t = line.trim();
    if (!t || t.indexOf('#') === 0) continue;
    const code = t.split(/\s|\|/)[0].trim();
    if (/^\d+$/.test(code)) set.add(code);
  }
  return Array.from(set).sort();
}

async function main() {
  const args = process.argv.slice(2);
  let batchName = 'Cap nhat manifest';
  let newCodes = [];
  if (args.indexOf('--from-db-export') >= 0) {
    const i = args.indexOf('--from-db-export');
    newCodes = codesFromExportFile(args[i + 1]);
    batchName = 'Tu DB export';
  } else {
    const bi = args.indexOf('--record-batch');
    if (bi >= 0 && args[bi + 1]) batchName = args[bi + 1];
    const xlsx = args.find(a => a.endsWith('.xlsx')) || xlsxDefault;
    const excelCodes = codesFromExcel(xlsx);
    const sim = await loadSimStudentCodes();
    newCodes = excelCodes.filter(c => sim.has(c));
    console.log('Excel unique', excelCodes.length, 'co SIM_Student', newCodes.length);
  }
  const { set: existing } = loadManifest();
  let added = 0;
  const now = new Date();
  const pad = n => (n < 10 ? '0' + n : '' + n);
  const dateStr = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
  const header = [];
  if (!fs.existsSync(manifestPath)) {
    header.push('# VIEC_LAM.2026 — StudentCode da import (PollNew plan VIEC_LAM.2026)');
    header.push('# Format: StudentCode|NgayGhi|Nguon');
    header.push('');
  }
  const outLines = fs.existsSync(manifestPath)
    ? fs.readFileSync(manifestPath, 'utf8').split(/\r?\n/)
    : header;
  outLines.push('# Batch: ' + batchName + ' — ' + dateStr);
  for (const code of newCodes) {
    if (existing.has(code)) continue;
    existing.add(code);
    outLines.push(code + '|' + dateStr + '|' + batchName);
    added++;
  }
  outLines.push('');
  fs.writeFileSync(manifestPath, outLines.join('\r\n'), 'utf8');
  console.log('Manifest', manifestPath);
  console.log('Tong ma trong manifest:', existing.size, 'Them moi lan nay:', added);
}

main().catch(e => { console.error(e); process.exit(1); });

