    if (!code) continue;
    rowCountMssv++;
    countByCode[code] = (countByCode[code] || 0) + 1;
    const ts = row[0];
    allRows.push({
      excelRow: i + 1,
      code,
      stt: row[1],
      name: row[4] != null ? String(row[4]).trim() : '',
      time: ts,
      row,
    });
    const prev = byCode.get(code);
    if (!prev || (typeof ts === 'number' && typeof prev.ts === 'number' && ts >= prev.ts)) {
      byCode.set(code, { row, ts, excelRow: i + 1, name: row[4] != null ? String(row[4]).trim() : '' });
    }
  }
  return { data, sheetName: sn, rowCountMssv, countByCode, byCode, allRows };
}

function buildStudentRecords(byCode) {
  const mapErrors = [];
  const students = [];
  for (const [code, meta] of byCode.entries()) {
    const details = buildDetails(meta.row);
    if (!details.length) {
      mapErrors.push({ code, excelRow: meta.excelRow, reason: 'Khong map cau tra loi (cot 5?)' });
      continue;
    }
    if (!pickAnswer('20201', meta.row[5])) {
      mapErrors.push({ code, excelRow: meta.excelRow, reason: 'Tinh trang VL khong khop: ' + meta.row[5] });
      continue;
    }
    students.push({
      code,
      name: meta.name,
      created: excelDateToSql(meta.ts),
      details,
      excelRow: meta.excelRow,
    });
  }
  students.sort((a, b) => a.code.localeCompare(b.code));
  return { students, mapErrors };
}

function writeImportSql(studentsToRun, options) {
  const sql = [];
  sql.push('/*');
  sql.push('\t' + options.headerComment.replace(/\r?\n/g, '\r\n\t'));
  sql.push('\tSo SV trong RUN: ' + studentsToRun.length);
  sql.push('\tChay SSMS -> USE thienhaso_SIMS_TC_NamSaiGon -> F5');
  sql.push('*/');
  sql.push('Use [thienhaso_SIMS_TC_NamSaiGon]');
  sql.push('Go');
  sql.push('Set Nocount On');
  sql.push('Declare @PlanID int, @SurveyID int = 2');
  sql.push('Select @PlanID = POL_NEW_Plan.PlanID From POL_NEW_Plan Where POL_NEW_Plan.PlanCode = N\'VIEC_LAM.2026\'');
  sql.push('If @PlanID Is Null');
  sql.push('Begin');
  sql.push('\tRaiserror(N\'Chua co Plan VIEC_LAM.2026\', 16, 1)');
  sql.push('\tReturn');
  sql.push('End');
  sql.push('Declare @Ok int = 0, @Skip int = 0, @Err int = 0');
  sql.push('Declare @StudentCode nvarchar(50), @StudentID bigint, @Username nvarchar(50), @ResponseID bigint');
  sql.push('');
  const desc = options.importDescription || 'Import Excel 2026';
  for (const st of studentsToRun) {
    const createdClause = st.created ? "Cast(N'" + st.created + "' As DateTime)" : 'GetDate()';
    sql.push('Begin Try');
    sql.push('\tSet @StudentCode = N\'' + escSql(st.code) + '\'');
    sql.push('\tSet @StudentID = Null');
    sql.push('\tSet @Username = Null');
    sql.push('\tSet @ResponseID = Null');
    sql.push('\tSelect Top 1 @StudentID = SIM_Student.StudentID From SIM_Student Where SIM_Student.StudentCode = @StudentCode And SIM_Student.IsDeleted = 0');
    sql.push('\tIf @StudentID Is Null');
    sql.push('\tBegin');
    sql.push('\t\tSet @Err = @Err + 1');
    sql.push('\t\tPrint N\'Loi: khong tim thay SV \' + @StudentCode');
    sql.push('\tEnd');
    sql.push('\tElse If Exists (');
    sql.push('\t\tSelect 1 From POL_NEW_Response');
    sql.push('\t\tInner Join POL_NEW_Plan On POL_NEW_Plan.PlanID = POL_NEW_Response.PlanID');
    sql.push('\t\tWhere POL_NEW_Plan.PlanCode = N\'VIEC_LAM.2026\'');
    sql.push('\t\t\tAnd POL_NEW_Response.StudentID = @StudentID');
    sql.push('\t\t\tAnd POL_NEW_Response.IsDeleted = 0');
    sql.push('\t)');
    sql.push('\tBegin');
    sql.push('\t\tSet @Skip = @Skip + 1');
    sql.push('\tEnd');
    sql.push('\tElse');
    sql.push('\tBegin');
    sql.push('\t\tSelect Top 1 @Username = SYS_User.Username From SYS_User Where SYS_User.StudentID = @StudentID And SYS_User.IsActived = 1');
    sql.push('\t\tInsert Into POL_NEW_Response (');
    sql.push('\t\t\tPlanID, SurveyID, Username, StudentID, PersonCode, PersonName, FullName,');
    sql.push('\t\t\tStatus, Description, CreatedUser, CreatedDate');
    sql.push('\t\t)');
    sql.push('\t\tSelect');
    sql.push('\t\t\t@PlanID, @SurveyID, @Username, @StudentID, @StudentCode,');
    sql.push('\t\t\tLeft(SIM_Student.StudentFirstName + N\' \' + SIM_Student.StudentLastName, 50),');
    sql.push('\t\t\tLeft(SIM_Student.StudentFirstName + N\' \' + SIM_Student.StudentLastName, 100),');
    sql.push('\t\t\t1, N\'' + escSql(desc) + '\', N\'import_excel\', ' + createdClause);
    sql.push('\t\tFrom SIM_Student Where SIM_Student.StudentID = @StudentID');
    sql.push('\t\tSet @ResponseID = Cast(Scope_Identity() As bigint)');
    for (const d of st.details) {
      sql.push('\t\tInsert Into POL_NEW_ResponseDetail (ResponseID, QuestionID, SectionID, OrderIndex, DoAnswerID, DoAnswerIndex, DoAnswerContent)');
      sql.push('\t\tValues (@ResponseID, ' + d.questionId + ', ' + d.sectionId + ', ' + d.orderIndex +
        ', N\'' + escSql(d.doAnswerId) + '\', N\'' + escSql(d.doAnswerIndex) + '\', N\'' + escSql(d.doAnswerContent) + '\')');
    }
    sql.push('\t\tSet @Ok = @Ok + 1');
    sql.push('\tEnd');
    sql.push('End Try');
    sql.push('Begin Catch');
    sql.push('\tSet @Err = @Err + 1');
    sql.push('\tPrint N\'Loi SV \' + IsNull(@StudentCode, N\'?\') + N\': \' + Error_Message()');
    sql.push('End Catch');
    sql.push('');
  }
  sql.push('Select @Ok As DaImport, @Skip As BoQuaDaCoPhieu, @Err As Loi');
  sql.push('Go');
  return sql.join('\r\n');
}

