/**
 * Import Cao đẳng — mẫu 2
 * Thu tu: (1) manifest da import (2) trung Excel (3) ma loi SIM (4) sinh RUN.sql
 * Chay: node run_import_mau2_cao_dang.js
 *       node run_import_mau2_cao_dang.js "duong\file.xlsx"
 */
const fs = require('fs');
const path = require('path');
const lib = require('./import_vieclam_lib');

const baseDir = __dirname;
const mau2Dir = path.join(baseDir, 'mẫu 2');
const logDir = path.join(mau2Dir, 'log');
const manifestPath = path.join(baseDir, 'manifest_VIEC_LAM_2026_da_import.txt');
const studentSql = path.join(baseDir, '..', '..', 'sql-table', 'new-table 01.10.2026', 'data -studenbt.sql');
const outSql = path.join(baseDir, '..', '..', 'sql-table', 'patches', '20261003_import_VIEC_LAM_cao_dang_RUN.sql');

function findXlsx() {
  const arg = process.argv.find(a => a.indexOf('.xlsx') >= 0);
  if (arg && fs.existsSync(arg)) return arg;
  if (!fs.existsSync(mau2Dir)) return null;
  const files = fs.readdirSync(mau2Dir).filter(f => f.toLowerCase().endsWith('.xlsx'));
  if (files.length === 0) return null;
  if (files.length === 1) return path.join(mau2Dir, files[0]);
  const prefer = files.find(f => /cao|cd|mau\s*2/i.test(f)) || files[0];
  return path.join(mau2Dir, prefer);
}

function ensureDir(d) {
  if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
}

function writeTxt(fp, lines) {
  fs.writeFileSync(fp, lines.join('\r\n') + '\r\n', 'utf8');
}

async function main() {
  const xlsxPath = findXlsx();
  if (!xlsxPath) {
    console.error('Khong tim thay file .xlsx trong:', mau2Dir);
    console.error('Dat file ket qua Cao dang vao thu muc "mau 2" hoac truyen duong dan .xlsx');
    process.exit(1);
  }
  ensureDir(logDir);
  const manifest = lib.loadManifestCodes(manifestPath);
  const simCodes = await lib.loadSimStudentCodes(studentSql);
  const parsed = lib.parseExcel(xlsxPath);
  const { students, mapErrors } = lib.buildStudentRecords(parsed.byCode);
  const studentByCode = {};
  for (const st of students) studentByCode[st.code] = st;
  const step1Manifest = [];
  const step2DupCodes = new Set();
  const step3LoiSim = [];
  const step3MapErr = [];
  const step4Run = [];
  for (const code of Object.keys(parsed.countByCode)) {
    if (parsed.countByCode[code] > 1) step2DupCodes.add(code);
  }
  const dupRowLines = [];
  dupRowLines.push('BUOC 2 — DONG EXCEL TRUNG MSSV (cot HSSV tu nhap)');
  dupRowLines.push('File: ' + xlsxPath);
  dupRowLines.push('Import giu 1 dong / ma (Thoi gian gui moi nhat)');
  dupRowLines.push('');
  dupRowLines.push('ExcelRow\tMSSV\tSoLan\tSTT\tHoTen');
  for (const r of parsed.allRows) {
    if (parsed.countByCode[r.code] <= 1) continue;
    dupRowLines.push(r.excelRow + '\t' + r.code + '\t' + parsed.countByCode[r.code] + '\t' +
      (r.stt != null ? r.stt : '') + '\t' + r.name);
  }
  for (const st of students) {
    if (manifest.has(st.code)) {
      step1Manifest.push(st);
      continue;
    }
    if (!simCodes.has(st.code)) {
      step3LoiSim.push(st);
      continue;
    }
    step4Run.push(st);
  }
  for (const e of mapErrors) {
    if (manifest.has(e.code)) continue;
    step3MapErr.push(e);
  }
  const manLines = [];
  manLines.push('BUOC 1 — MSSV DA IMPORT TRUOC (manifest_VIEC_LAM_2026_da_import.txt)');
  manLines.push('So ma: ' + step1Manifest.length);
  manLines.push('');
  manLines.push('MSSV\tHoTenExcel\tExcelRow');
  for (const st of step1Manifest) {
    manLines.push(st.code + '\t' + st.name + '\t' + st.excelRow);
  }
  const loiLines = [];
  loiLines.push('BUOC 3 — MA LOI (khong co SIM_Student.StudentCode trong dump)');
  loiLines.push('So ma: ' + step3LoiSim.length);
  loiLines.push('');
  loiLines.push('MSSV\tHoTenExcel\tExcelRow');
  for (const st of step3LoiSim) {
    loiLines.push(st.code + '\t' + st.name + '\t' + st.excelRow);
  }
  if (step3MapErr.length) {
    loiLines.push('');
    loiLines.push('Loi map cau tra loi Excel (khong vao RUN):');
    for (const e of step3MapErr) {
      loiLines.push(e.code + '\tRow ' + e.excelRow + '\t' + e.reason);
    }
  }
  const runLines = [];
  runLines.push('BUOC 4 — SE GHI VAO RUN.sql (sau buoc 1-3)');
  runLines.push('So ma: ' + step4Run.length);
  runLines.push('SQL: ' + outSql);
  runLines.push('');
  runLines.push('MSSV\tHoTenExcel');
  for (const st of step4Run) {
    runLines.push(st.code + '\t' + st.name);
  }
  const summary = [];
  summary.push('TOM TAT IMPORT CAO DANG — ' + new Date().toISOString().slice(0, 19));
  summary.push('Excel: ' + xlsxPath);
  summary.push('Sheet: ' + parsed.sheetName);
  summary.push('Dong co MSSV: ' + parsed.rowCountMssv);
  summary.push('Ma unique (sau gop trung): ' + students.length);
  summary.push('');
  summary.push('1. Da import truoc (manifest): ' + step1Manifest.length);
  summary.push('2. Ma co trung trong Excel: ' + step2DupCodes.size + ' ma, ' +
    parsed.allRows.filter(r => parsed.countByCode[r.code] > 1).length + ' dong');
  summary.push('3. Ma loi SIM_Student: ' + step3LoiSim.length);
  summary.push('   Map cau tra loi loi: ' + step3MapErr.length);
  summary.push('4. Ghi RUN.sql: ' + step4Run.length);
  summary.push('');
  summary.push('Sau F5 RUN.sql thanh cong:');
  summary.push('  node sync_manifest_da_import.js --record-batch "Cao dang dot ..."');
  writeTxt(path.join(logDir, '00_tom_tat.txt'), summary);
  writeTxt(path.join(logDir, '01_da_import_manifest.txt'), manLines);
  writeTxt(path.join(logDir, '02_trung_trong_excel.txt'), dupRowLines);
  writeTxt(path.join(logDir, '03_ma_loi.txt'), loiLines);
  writeTxt(path.join(logDir, '04_se_import_RUN.txt'), runLines);
  const sqlBody = lib.writeImportSql(step4Run, {
    headerComment: 'Import PollNew VIEC_LAM.2026 — Cao dang (mau 2)\r\nNguon: ' + xlsxPath,
    importDescription: 'Import Excel Cao dang 2026',
  });
  fs.writeFileSync(outSql, sqlBody, 'utf8');
  console.log('Excel', xlsxPath);
  console.log('Log ->', logDir);
  console.log('RUN.sql ->', outSql);
  console.log('Manifest skip', step1Manifest.length, 'Loi SIM', step3LoiSim.length, 'RUN', step4Run.length);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

