using System;
using System.Data;
using System.Web;
using System.Web.UI;
using WebGlobal;
using PollObject;
namespace InformationWeb.Controls.PollNew.Report
{
    public partial class Detail : ControlBase
    {
        public long? ResponseID
        {
            get
            {
                if (ViewState["ResponseID" + ClientID] != null)
                    return Convert.ToInt64(ViewState["ResponseID" + ClientID]);
                return null;
            }
            set { ViewState["ResponseID" + ClientID] = value; }
        }
        private void GetRequest()
        {
            ResponseID = WebGlobal.GetRequestDecodeInt64(Request["id"]);
        }
        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                GetRequest();
                lnkBack.NavigateUrl = DCore.Globals.ApplicationVRoot + "/Pages/PollNew/Report/ReportList.aspx";
                LoadData();
            }
        }
        private void LoadData()
        {
            if (ResponseID == null)
            {
                ShowError("Không xác định được phiếu khảo sát.");
                return;
            }
            POL_NEW_Response obj = new POL_NEW_Response();
            obj.ResponseID = ResponseID;
            if (!obj.Get())
            {
                ShowError("Không tìm thấy phiếu khảo sát hoặc đã bị xóa.");
                return;
            }
            BindHeader(obj);
            DataTable dtbDetail = obj.GetDetailLines(ResponseID);
            if (dtbDetail == null)
            {
                ShowError("Không tải được chi tiết câu trả lời. Chạy patch SQL POL_NEW_Response_report_detail.");
                return;
            }
            POL_NEW_Answer objAnswer = new POL_NEW_Answer();
            DataTable dtbAnswer = objAnswer.GetBySurveyID(obj.SurveyID);
            DataTable dtbLines = BuildDisplayLines(dtbDetail, dtbAnswer);
            rptLines.DataSource = dtbLines;
            rptLines.DataBind();
            pnlContent.Visible = true;
            pnlError.Visible = false;
        }
        private void ShowError(string strMessage)
        {
            pnlContent.Visible = false;
            pnlError.Visible = true;
            lblError.Text = strMessage;
        }
        private void BindHeader(POL_NEW_Response obj)
        {
            string strCode = obj.PersonCode;
            if (obj.GetDataTable("POL_NEW_Response_GET", "@ResponseID", ResponseID) != null)
            {
                DataTable dtbH = obj.GetDataTable("POL_NEW_Response_GET", "@ResponseID", ResponseID);
                if (dtbH != null && dtbH.Rows.Count > 0)
                {
                    DataRow drwH = dtbH.Rows[0];
                    if (drwH["StudentCode"] != DBNull.Value && drwH["StudentCode"].ToString().Trim() != "")
                        strCode = drwH["StudentCode"].ToString();
                    lblStudentCode.Text = strCode;
                    lblFullName.Text = PickName(drwH["FullName"], drwH["PersonName"], drwH["StudentFullNameFromSIM"], obj.FullName);
                    lblClassName.Text = NullStr(drwH["ClassName"]);
                    lblFacultyName.Text = NullStr(drwH["FacultyName"]);
                    lblPlan.Text = String.Format("{0} — {1}", drwH["PlanCode"], drwH["PlanName"]);
                    lblSurvey.Text = String.Format("{0} — {1}", drwH["SurveyCode"], drwH["SurveyName"]);
                    if (drwH["CreatedDate"] != DBNull.Value)
                        lblCreatedDate.Text = Convert.ToDateTime(drwH["CreatedDate"]).ToString("dd/MM/yyyy HH:mm");
                    lblCreatedUser.Text = NullStr(drwH["CreatedUser"]);
                    if (drwH["Description"] != DBNull.Value && drwH["Description"].ToString().Trim() != "")
                        lblCreatedUser.Text = lblCreatedUser.Text + " (" + drwH["Description"] + ")";
                    return;
                }
            }
            lblStudentCode.Text = strCode;
            lblFullName.Text = obj.FullName;
            lblClassName.Text = obj.ClassName;
            lblFacultyName.Text = obj.FacultyName;
            lblPlan.Text = obj.PlanID.ToString();
            lblSurvey.Text = obj.SurveyID.ToString();
            if (obj.CreatedDate != null)
                lblCreatedDate.Text = obj.CreatedDate.Value.ToString("dd/MM/yyyy HH:mm");
            lblCreatedUser.Text = obj.CreatedUser;
        }
        private string PickName(object o1, object o2, object o3, string strFallback)
        {
            if (o1 != null && o1 != DBNull.Value && o1.ToString().Trim() != "")
                return o1.ToString();
            if (o2 != null && o2 != DBNull.Value && o2.ToString().Trim() != "")
                return o2.ToString();
            if (o3 != null && o3 != DBNull.Value && o3.ToString().Trim() != "")
                return o3.ToString();
            return strFallback ?? "";
        }
        private string NullStr(object obj)
        {
            if (obj == null || obj == DBNull.Value)
                return "";
            return obj.ToString();
        }
        private DataTable BuildDisplayLines(DataTable dtbDetail, DataTable dtbAnswer)
        {
            DataTable dtb = new DataTable();
            dtb.Columns.Add("ColSpan", typeof(int));
            dtb.Columns.Add("Label", typeof(string));
            dtb.Columns.Add("Value", typeof(string));
            dtb.Columns.Add("RowCss", typeof(string));
            string strLastSection = null;
            string strLastGroup = null;
            foreach (DataRow drw in dtbDetail.Rows)
            {
                string strSection = NullStr(drw["SectionName"]);
                if (strSection != "" && strSection != strLastSection)
                {
                    AddLine(dtb, 2, strSection, "", "table-secondary fw-bold");
                    strLastSection = strSection;
                    strLastGroup = null;
                }
                string strGroup = NullStr(drw["GroupName"]);
                if (strGroup != "" && strGroup != strLastGroup)
                {
                    AddLine(dtb, 2, strGroup, "", "table-light fw-bold");
                    strLastGroup = strGroup;
                }
                int intQType = Convert.ToInt32(drw["QuestionTypeID"]);
                int intQuestionID = Convert.ToInt32(drw["QuestionID"]);
                string strQName = NullStr(drw["QuestionName"]);
                string strContent = NullStr(drw["DoAnswerContent"]);
                string strDoAnswerId = NullStr(drw["DoAnswerID"]);
                if (intQType == 5)
                {
                    ExpandComposite(dtb, intQuestionID, strDoAnswerId, strContent, dtbAnswer);
                }
                else
                {
                    string strLabel = strQName;
                    if (strLabel == "")
                        strLabel = NullStr(drw["QuestionCode"]);
                    AddLine(dtb, 1, strLabel, strContent, "");
                }
            }
            return dtb;
        }
        private void ExpandComposite(DataTable dtb, int intQuestionID, string strDoAnswerId, string strContent, DataTable dtbAnswer)
        {
            string[] arrId = strDoAnswerId.Split(new char[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
            if (arrId.Length == 0)
            {
                if (strContent.Trim() != "")
                    AddLine(dtb, 1, "Nội dung", strContent, "");
                return;
            }
            string[] arrVal = SplitAnswerValues(strContent, arrId.Length);
            for (int i = 0; i < arrId.Length; i++)
            {
                int intAid = 0;
                int.TryParse(arrId[i].Trim(), out intAid);
                string strLabel = GetAnswerName(dtbAnswer, intQuestionID, intAid);
                string strVal = i < arrVal.Length ? arrVal[i].Trim() : "";
                if (strLabel == "" && strVal == "")
                    continue;
                if (strLabel != "" && strVal != "" && strLabel == strVal)
                    AddLine(dtb, 1, strLabel, "—", "");
                else if (strLabel == "" && strVal != "")
                    AddLine(dtb, 1, "Ô trả lời " + (i + 1).ToString(), strVal, "");
                else
                    AddLine(dtb, 1, strLabel, strVal, "");
            }
        }
        private string[] SplitAnswerValues(string strContent, int intCount)
        {
            if (strContent == null)
                strContent = "";
            strContent = strContent.Trim();
            if (strContent == "")
                return new string[0];
            string[] arrSemi = strContent.Split(new string[] { "; " }, StringSplitOptions.None);
            if (arrSemi.Length >= intCount)
                return arrSemi;
            arrSemi = strContent.Split(';');
            if (arrSemi.Length >= intCount)
            {
                for (int i = 0; i < arrSemi.Length; i++)
                    arrSemi[i] = arrSemi[i].Trim();
                return arrSemi;
            }
            return new string[] { strContent };
        }
        private string GetAnswerName(DataTable dtbAnswer, int intQuestionID, int intAnswerID)
        {
            if (dtbAnswer == null || intAnswerID <= 0)
                return "";
            foreach (DataRow drw in dtbAnswer.Rows)
            {
                if (Convert.ToInt32(drw["QuestionID"]) != intQuestionID)
                    continue;
                if (Convert.ToInt32(drw["AnswerID"]) == intAnswerID)
                    return NullStr(drw["AnswerName"]);
            }
            return "";
        }
        private void AddLine(DataTable dtb, int intColSpan, string strLabel, string strValue, string strRowCss)
        {
            DataRow drw = dtb.NewRow();
            drw["ColSpan"] = intColSpan;
            drw["Label"] = strLabel;
            drw["Value"] = strValue;
            drw["RowCss"] = strRowCss;
            dtb.Rows.Add(drw);
        }
        protected string RenderLineHtml(object objColSpan, object objLabel, object objValue)
        {
            int intColSpan = Convert.ToInt32(objColSpan);
            string strLabel = HttpUtility.HtmlEncode(NullStr(objLabel));
            string strValue = HttpUtility.HtmlEncode(NullStr(objValue));
            if (intColSpan == 2)
                return "<td colspan=\"2\">" + strLabel + "</td>";
            return "<td>" + strLabel + "</td><td>" + strValue + "</td>";
        }
    }
}

