using System;
using System.Collections.Generic;
using System.Data;
using System.Text;
using System.Web;
namespace InformationWeb.Controls.PollNew.Report
{
    public static class ReportExportHelper
    {
        public static void ExportFlatToExcel(DataTable dtbFlat, HttpResponse response, string strFilePrefix)
        {
            if (dtbFlat == null || dtbFlat.Rows.Count == 0)
            {
                throw new InvalidOperationException("Không có dữ liệu để xuất Excel.");
            }
            List<QuestionCol> lstQuestions = BuildQuestionColumns(dtbFlat);
            Dictionary<long, ResponseRow> dicRows = BuildResponseRows(dtbFlat, lstQuestions);
            if (dicRows.Count == 0)
            {
                throw new InvalidOperationException("Không có dữ liệu để xuất Excel.");
            }
            StringBuilder sb = new StringBuilder();
            sb.Append("<html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" /></head><body>");
            sb.Append("<table border=\"1\">");
            sb.Append("<tr style=\"background-color:#4472C4;color:#fff;font-weight:bold\">");
            sb.Append("<td>Thời gian gửi</td>");
            sb.Append("<td>STT</td>");
            sb.Append("<td>MSSV</td>");
            sb.Append("<td>Họ và tên</td>");
            sb.Append("<td>Lớp</td>");
            sb.Append("<td>Khoa</td>");
            sb.Append("<td>Kế hoạch</td>");
            sb.Append("<td>Mẫu KS</td>");
            foreach (QuestionCol itemCol in lstQuestions)
            {
                sb.Append("<td>");
                sb.Append(Html(itemCol.HeaderText));
                sb.Append("</td>");
            }
            sb.Append("</tr>");
            int intStt = 0;
            foreach (KeyValuePair<long, ResponseRow> itemPair in dicRows)
            {
                intStt++;
                ResponseRow itemRow = itemPair.Value;
                sb.Append("<tr>");
                sb.Append("<td>");
                sb.Append(Html(FormatDate(itemRow.CreatedDate)));
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(intStt.ToString());
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(Html(itemRow.StudentCode));
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(Html(itemRow.StudentFullName));
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(Html(itemRow.ClassName));
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(Html(itemRow.FacultyName));
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(Html(itemRow.PlanCode));
                sb.Append("</td>");
                sb.Append("<td>");
                sb.Append(Html(itemRow.SurveyCode));
                sb.Append("</td>");
                foreach (QuestionCol itemCol in lstQuestions)
                {
                    string strVal = "";
                    if (itemRow.Answers.ContainsKey(itemCol.QuestionID))
                        strVal = itemRow.Answers[itemCol.QuestionID];
                    sb.Append("<td>");
                    sb.Append(Html(strVal));
                    sb.Append("</td>");
                }
                sb.Append("</tr>");
            }
            sb.Append("</table></body></html>");
            string strFileName = strFilePrefix + "_" + DateTime.Now.ToString("yyyyMMdd_HHmm") + ".xls";
            response.Clear();
            response.Buffer = true;
            response.ContentType = "application/vnd.ms-excel";
            response.AddHeader("Content-Disposition", "attachment; filename=" + strFileName);
            response.ContentEncoding = Encoding.UTF8;
            response.BinaryWrite(Encoding.UTF8.GetPreamble());
            response.Write(sb.ToString());
            response.End();
        }
        private static List<QuestionCol> BuildQuestionColumns(DataTable dtbFlat)
        {
            List<QuestionCol> lst = new List<QuestionCol>();
            Dictionary<int, QuestionCol> dic = new Dictionary<int, QuestionCol>();
            foreach (DataRow drw in dtbFlat.Rows)
            {
                int intQid = Convert.ToInt32(drw["QuestionID"]);
                if (dic.ContainsKey(intQid))
                    continue;
                QuestionCol itemCol = new QuestionCol();
                itemCol.QuestionID = intQid;
                itemCol.SectionOrderIndex = Convert.ToInt32(drw["SectionOrderIndex"]);
                itemCol.QuestionOrderIndex = Convert.ToInt32(drw["QuestionOrderIndex"]);
                string strName = NullStr(drw["QuestionName"]);
                if (strName == "")
                    strName = NullStr(drw["QuestionCode"]);
                itemCol.HeaderText = strName;
                dic.Add(intQid, itemCol);
            }
            foreach (KeyValuePair<int, QuestionCol> itemPair in dic)
            {
                lst.Add(itemPair.Value);
            }
            lst.Sort(delegate(QuestionCol a, QuestionCol b)
            {
                int intCmp = a.SectionOrderIndex.CompareTo(b.SectionOrderIndex);
                if (intCmp != 0)
                    return intCmp;
                return a.QuestionOrderIndex.CompareTo(b.QuestionOrderIndex);
            });
            return lst;
        }
        private static Dictionary<long, ResponseRow> BuildResponseRows(DataTable dtbFlat, List<QuestionCol> lstQuestions)
        {
            Dictionary<long, ResponseRow> dic = new Dictionary<long, ResponseRow>();
            foreach (DataRow drw in dtbFlat.Rows)
            {
                long lngId = Convert.ToInt64(drw["ResponseID"]);
                ResponseRow itemRow;
                if (!dic.TryGetValue(lngId, out itemRow))
                {
                    itemRow = new ResponseRow();
                    itemRow.ResponseID = lngId;
                    if (drw["CreatedDate"] != DBNull.Value)
                        itemRow.CreatedDate = Convert.ToDateTime(drw["CreatedDate"]);
                    itemRow.StudentCode = NullStr(drw["StudentCode"]);
                    itemRow.StudentFullName = NullStr(drw["StudentFullName"]);
                    itemRow.ClassName = NullStr(drw["ClassName"]);
                    itemRow.FacultyName = NullStr(drw["FacultyName"]);
                    itemRow.PlanCode = NullStr(drw["PlanCode"]);
                    itemRow.SurveyCode = NullStr(drw["SurveyCode"]);
                    dic.Add(lngId, itemRow);
                }
                int intQid = Convert.ToInt32(drw["QuestionID"]);
                string strContent = NullStr(drw["DoAnswerContent"]);
                strContent = strContent.Replace("; ", " | ");
                if (itemRow.Answers.ContainsKey(intQid))
                {
                    if (strContent != "")
                        itemRow.Answers[intQid] = itemRow.Answers[intQid] + " | " + strContent;
                }
                else
                {
                    itemRow.Answers[intQid] = strContent;
                }
            }
            return dic;
        }
        private static string FormatDate(DateTime? dtm)
        {
            if (dtm == null)
                return "";
            return dtm.Value.ToString("dd/MM/yyyy HH:mm");
        }
        private static string NullStr(object obj)
        {
            if (obj == null || obj == DBNull.Value)
                return "";
            return obj.ToString();
        }
        private static string Html(string str)
        {
            if (str == null)
                return "";
            return HttpUtility.HtmlEncode(str);
        }
        private class QuestionCol
        {
            public int QuestionID;
            public int SectionOrderIndex;
            public int QuestionOrderIndex;
            public string HeaderText;
        }
        private class ResponseRow
        {
            public long ResponseID;
            public DateTime? CreatedDate;
            public string StudentCode;
            public string StudentFullName;
            public string ClassName;
            public string FacultyName;
            public string PlanCode;
            public string SurveyCode;
            public Dictionary<int, string> Answers = new Dictionary<int, string>();
        }
    }
}

